import datetime
import re

from ta_moler.events.rtg_ctrl.genericrtg_ctrl_lineevent import GenericRtgCtrlLineEvent


class CcsCrashed(GenericRtgCtrlLineEvent):
    """Ccs crashed event class."""

    # Example line: [ 1164.350680] platform[876]: ccs: CCSLiteExe 0x123b has crashed. Core dump /var/tmp/diagn/CCSLiteExe_5806_.core.xz
    _re_ccs_crashed = re.compile(r"CCSLiteExe (?P<NUMBER>0x[a-f0-9]+) has crashed")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for ccs crashed.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(CcsCrashed, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self._re_ccs_crashed], match="any"
        )


EVENT_OUTPUT = """[  389.255534] platform[876]: ccs:
[  719.360690] platform[876]: ccs: 43227 09360.838  rejected packet
[ 1150.492383] platform[876]: ccs: SCH(123b): FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected, expectedTime=[739.5] receivedTime=[258.1] ticksDiff=4476531
[ 1150.493058] platform[876]: ccs: SCH(1239): FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected, expectedTime=[739.5] receivedTime=[258.1] ticksDiff=4476998
[ 1164.350680] platform[876]: ccs: CCSLiteExe 0x123b has crashed. Core dump /var/tmp/diagn/CCSLiteExe_5806_.core.xz"""

EVENT_KWARGS = {"till_occurs_times": 1}

EVENT_RESULT = [
    {
        "line": "[ 1164.350680] platform[876]: ccs: CCSLiteExe 0x123b has crashed. Core dump /var/tmp/diagn/CCSLiteExe_5806_.core.xz",
        "groups": ("0x123b",),
        "named_groups": {"NUMBER": "0x123b"},
        "matched": "CCSLiteExe 0x123b has crashed",
        "time": datetime.datetime.now(),
    }
]
